/**
 * Mirror of `eval::Event` / `eval_.Event`: one unit of evaluator output.
 * `value` is the per-chunk mean for value channels and `None` for discrete
 * events. Re-exposed as a uniffi record so Swift/Kotlin get a plain value
 * type; the conversion is a field-for-field move, no logic.
 */
public struct Event {
    public var timestampS: Double
    public var channel: String
    public var kind: String
    public var value: Double?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(timestampS: Double, channel: String, kind: String, value: Double?) {
        self.timestampS = timestampS
        self.channel = channel
        self.kind = kind
        self.value = value
    }
}

#if compiler(>=6)
extension Event: Sendable {}
#endif


extension Event: Equatable, Hashable {
    public static func ==(lhs: Event, rhs: Event) -> Bool {
        if lhs.timestampS != rhs.timestampS {
            return false
        }
        if lhs.channel != rhs.channel {
            return false
        }
        if lhs.kind != rhs.kind {
            return false
        }
        if lhs.value != rhs.value {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(timestampS)
        hasher.combine(channel)
        hasher.combine(kind)
        hasher.combine(value)
    }
}



