/**
 * Errors surfaced across the FFI boundary. Currently the only fallible step
 * is deserializing the IR-JSON wire format. `Display`/`Error` are implemented
 * by hand to avoid pulling in `thiserror` just for one variant.
 */
public enum RefrainError: Swift.Error {

    
    
    /**
     * The IR-JSON string could not be deserialized into a `Protocol`.
     */
    case InvalidIr(message: String
    )
    /**
     * `set_control` was called with a name that is not a declared control
     * (mirrors the Python evaluator raising `KeyError`).
     */
    case UnknownControl(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRefrainError: FfiConverterRustBuffer {
    typealias SwiftType = RefrainError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RefrainError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidIr(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .UnknownControl(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RefrainError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidIr(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .UnknownControl(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


