        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_refrain_core_checksum_method_refraincore_last_taps() != 62853) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_refrain_core_checksum_method_refraincore_set_clock_frozen() != 49829) {
        return InitializationResult.apiChecksumMismatch
    }
